}

html.codex-dream-skin button[class~="bg-token-foreground"] {
  background: var(--ds-accent) !important;
  color: var(--ds-on-accent) !important;
  box-shadow: 0 5px 14px rgb(var(--ds-accent-rgb) / .20) !important;
