html.codex-dream-skin article,
html.codex-dream-skin [data-message-author-role] { border-radius: 16px; }

@media (max-width: 1120px) {
  .dream-skin-status { display: none !important; }
  .dream-skin-home { --thread-content-max-width: min(940px, calc(100cqw - 30px)) !important; }
  .dream-skin-home > div:first-child > div:first-child > div:first-child { width: calc(100% - 28px) !important; }
}

@media (max-width: 900px) {
  .dream-skin-brand { left: 15px; }
  .dream-skin-brand b { font-size: 12px; }
  .dream-skin-home > div:first-child > div:first-child {
    flex-basis: 408px !important;
    min-height: 408px !important;
  }
  .dream-skin-home > div:first-child > div:first-child > div:first-child {
    height: 232px !important;
    min-height: 232px !important;
  }
  .dream-skin-home > div:first-child > div:first-child > div:first-child > div:first-child { padding: 0 26px; }
  .dream-skin-home > div:first-child > div:first-child > div:first-child > div:first-child > div:first-child {
    width: min(58%, 460px) !important;
  }
  .dream-skin-home [data-feature="game-source"] { font-size: 18px !important; }
  .dream-skin-home [data-feature="game-source"]::before { margin-bottom: 7px; font-size: 10px; }
  .dream-skin-home [data-feature="game-source"]::after { margin-top: 9px; font-size: 11px; }
  .dream-skin-home .group\/home-suggestions button { min-height: 112px !important; font-size: 12px !important; }
}

@media (prefers-reduced-motion: reduce) {
  html.codex-dream-skin *,
  html.codex-dream-skin *::before,
  html.codex-dream-skin *::after {
    scroll-behavior: auto !important;
    transition-duration: .01ms !important;
    animation-duration: .01ms !important;
    animation-iteration-count: 1 !important;
  }
}


/* ===== brand-tokens.css ===== */
/* ============================================================
   brand-tokens · 品牌文案的唯一入口
   ------------------------------------------------------------
   本皮肤默认是作者的 RX-78-2「白色装甲」配置。
   想改成你自己的版本，通常只需要动这一个文件的三行文案；
   壁纸换图请用 换壁纸.command（它会自动重新烘焙）。

   文案必须带引号 —— 它们最终被塞进 CSS 的 content:，例如
       --skin-nameplate: "MY MACHINE · CUSTOM BUILD";
   ============================================================ */
html.codex-dream-skin {
  /* 顶栏那条小字铭牌。字距被拉开过，太长会挤掉窗口标题 */
  --skin-nameplate: "RX-78-2 GUNDAM · SCV-70 WHITE BASE · 限定皮肤";

  /* 首页标题下方那行超大淡字水印。字距 .38em，4-6 个字符最好看 */
  --skin-watermark: "E F S F";

  /* 右下角拍立得照片下方的标签 */
  --skin-photo-label: "SCV-70 WHITE BASE";
}

/* ===== v2.css ===== */
/* =====================================================================
   Yihan v2 · Liquid-Glass chrome (light scheme, Apple iOS-26 inspired)
   Recipe: high blur + high saturation (vivid bleed-through) + a bright
   specular top edge + soft outer shadow + hairline light rim.
   Selectors doubled (.codex-dream-skin.codex-dream-skin) to win over the
   immersive !important rules above.  Pure CSS (no SVG) = L1, safe/fast.
   ===================================================================== */
:root.codex-dream-skin {
  /* specular / rim used across the glass surfaces */
  --lg-blur: blur(22px) saturate(185%);
  --lg-rim: inset 0 0 0 1px rgb(255 255 255 / .38);
  --lg-sheen: inset 0 1px 0 rgb(255 255 255 / .85),
              inset 0 8px 18px rgb(255 255 255 / .10),
              inset 0 -10px 20px rgb(var(--ds-accent-rgb) / .05);
  --lg-drop: 0 10px 30px rgb(var(--ds-bg-rgb) / .20);
}

/* (A) Sidebar — a single tall pane of liquid glass with a lit right edge */
html.codex-dream-skin.codex-dream-skin[data-dream-art-wide="true"]:has(main.main-surface)
  aside.app-shell-left-panel {
  background: linear-gradient(180deg,
    rgb(var(--ds-panel-rgb) / .60),
    rgb(var(--ds-panel-rgb) / .48)) !important;
  border-right: 1px solid rgb(255 255 255 / .5) !important;
  box-shadow: 10px 0 30px rgb(var(--ds-bg-rgb) / .14),
    inset -1px 0 0 rgb(var(--ds-accent-rgb) / .06),
    var(--lg-rim) !important;
  backdrop-filter: var(--lg-blur) !important;
}

/* (B) Sidebar rows — light glass chips; understated at rest, lit on hover */
html.codex-dream-skin.codex-dream-skin aside.app-shell-left-panel nav > button,
html.codex-dream-skin.codex-dream-skin aside.app-shell-left-panel nav > a {
  margin: 1px 2px !important;
  border: 1px solid rgb(255 255 255 / .32) !important;
  background: rgb(var(--ds-panel-rgb) / .34) !important;
  box-shadow: inset 0 1px 0 rgb(255 255 255 / .55),
    0 1px 2px rgb(var(--ds-bg-rgb) / .08) !important;
  backdrop-filter: blur(6px) saturate(150%) !important;
}
html.codex-dream-skin.codex-dream-skin aside.app-shell-left-panel nav > button:hover,
html.codex-dream-skin.codex-dream-skin aside.app-shell-left-panel nav > a:hover {
  border-color: rgb(255 255 255 / .6) !important;
  background: rgb(var(--ds-accent-rgb) / .10) !important;
  box-shadow: inset 0 1px 0 rgb(255 255 255 / .7),
    0 6px 16px rgb(var(--ds-bg-rgb) / .16) !important;
  transform: translateY(-1px) !important;
}

/* (C) Selected row — brightest glass, accent left rail + accent glow */
html.codex-dream-skin.codex-dream-skin aside.app-shell-left-panel [aria-current="page"],
html.codex-dream-skin.codex-dream-skin aside.app-shell-left-panel [class~="bg-token-list-hover-background"] {
  position: relative !important;
  background: linear-gradient(180deg,
    rgb(var(--ds-panel-rgb) / .82),
    rgb(var(--ds-panel-rgb) / .66)) !important;
  border: 1px solid rgb(var(--ds-accent-rgb) / .34) !important;
  border-radius: 11px !important;
  box-shadow: 0 8px 20px rgb(var(--ds-accent-rgb) / .18),
    var(--lg-sheen), var(--lg-rim) !important;
  backdrop-filter: var(--lg-blur) !important;
  color: var(--ds-text) !important;
  font-weight: 640 !important;
}
html.codex-dream-skin.codex-dream-skin aside.app-shell-left-panel [aria-current="page"]::before {
  content: "" !important;
  position: absolute !important;
  left: 4px; top: 50%; transform: translateY(-50%);
  width: 3px; height: 58%; border-radius: 3px;
  background: var(--ds-accent) !important;
  box-shadow: 0 0 8px rgb(var(--ds-accent-rgb) / .5) !important;
}
html.codex-dream-skin.codex-dream-skin aside.app-shell-left-panel [aria-current="page"] span {
  color: var(--ds-text) !important;
}

/* (D) Composer + home utility — the hero pieces get the fullest glass */
html.codex-dream-skin.codex-dream-skin[data-dream-art-wide="true"] .composer-surface-chrome {
  background: linear-gradient(180deg,
    rgb(var(--ds-panel-rgb) / .68),
    rgb(var(--ds-panel-rgb) / .54)) !important;
  border: 1px solid rgb(255 255 255 / .5) !important;
  box-shadow: 0 16px 40px rgb(var(--ds-bg-rgb) / .22),
    var(--lg-sheen), var(--lg-rim) !important;
  backdrop-filter: var(--lg-blur) !important;
}
html.codex-dream-skin.codex-dream-skin[data-dream-art-wide="true"] .dream-skin-home-utility {
  background: linear-gradient(180deg,
    rgb(var(--ds-panel-rgb) / .70),
    rgb(var(--ds-panel-rgb) / .58)) !important;
  box-shadow: inset 0 1px 0 rgb(255 255 255 / .7),
    inset 1px 0 rgb(255 255 255 / .4),
    inset -1px 0 rgb(255 255 255 / .4) !important;
  backdrop-filter: var(--lg-blur) !important;
}

/* (E) Suggestion cards — glass tiles, legible, with specular top */
html.codex-dream-skin.codex-dream-skin[data-dream-art-wide="true"]
  .dream-skin-home .group\/home-suggestions button {
