}
html.codex-dream-skin.codex-dream-skin[data-dream-art-wide="true"]
  .dream-skin-home .group\/home-suggestions button:hover {
  transform: translateY(-2px) !important;
  border-color: rgb(255 255 255 / .66) !important;
  box-shadow: 0 16px 36px rgb(var(--ds-bg-rgb) / .24),
